import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        final long MOD = 998244353L;
        int n = (int) nextLong(), m = (int) nextLong(), target = (int) nextLong();
        long[] dp = new long[64];
        dp[0] = 1;
        for (int i = 0; i < n; i++) {
            long[] nxt = new long[64];
            for (int old = 0; old < 64; old++)
                for (int v = 0; v <= m; v++) nxt[old ^ v] = (nxt[old ^ v] + dp[old]) % MOD;
            dp = nxt;
        }
        System.out.println(dp[target]);
    }
}

